function shareList(id){const l=lists.find(x=>x.id===id);const others=accounts.filter(a=>a.user_id&&a.user_id!==user.id&&a.accepted_at);openModal(`<h2>Distribuie lista</h2><p>${esc(l.name)} · Alegi cine poate vedea și modifica această listă.</p>${others.length?others.map(a=>`<label class="setting-row"><span class="account-email">${esc(a.email)}</span><input type="checkbox" ${members.some(m=>m.list_id===id&&m.user_id===a.user_id)?'checked':''} onchange="changeShare('${id}','${a.user_id}',this)"></label>`).join(''):'<p>Nu există încă alți membri. Invită-i din Setări → Administrare.</p>'}<p>Dacă nu selectezi pe nimeni, lista rămâne personală.</p>`)}
