function renderSettings(){$('settingsPanel').innerHTML=`<h2>Setări</h2><p class="settings-caption">MyList, așa cum vă place.</p><div class="settings-section"><h3>Cont</h3><p class="account-email">${esc(user.email)} · ${me()?.is_admin?'Administrator':'Membru'}</p><button class="outline" onclick="logout()">Deconectare</button></div><div class="settings-section"><h3>Afișare</h3><label class="setting-row">Temă<select aria-label="Temă" onchange="setTheme(this.value)">${[['light','Luminos'],['dark','Întunecat'],['system','Sistem']].map(([v,n])=>`<option value="${v}" ${themePreference===v?'selected':''}>${n}</option>`).join('')}</select></label><label class="setting-row"><span>Arată produsele cumpărate</span><input type="checkbox" ${!hideDone?'checked':''} onchange="hideDone=!this.checked"></label></div>${me()?.is_admin?`<div class="settings-section"><h3>Administrare · Invitații</h3><form class="invite-form" onsubmit="invite(event)"><label for="inviteEmail">Adresa de e-mail</label><input id="inviteEmail" type="email" required autocomplete="email" placeholder="nume@exemplu.ro"><button class="primary" type="submit">Trimite invitația</button></form><div class="invitations">${accounts.map(a=>`<div class="setting-row"><span class="account-email">${esc(a.email)}<small>${a.accepted_at?'Cont activ':'În așteptare'}</small></span>${!a.accepted_at?`<button class="outline" onclick="cancelInvite('${esc(a.email)}')">Retrage</button>`:''}</div>`).join('')}</div><p>Invitația oferă acces la aplicație. Listele se distribuie separat din meniul fiecărei liste.</p></div>`:''}<div class="settings-section"><h3>Date și salvare</h3><p>Listele sunt salvate în contul tău. Cele partajate se actualizează automat, la câteva secunde.</p><div class="data-actions"><button class="outline" onclick="exportLists()">Exportă listele</button><button class="outline" onclick="$('importLists').click()">Importă liste</button></div><input id="importLists" type="file" accept="application/json" hidden onchange="importLists(this)"><div id="localMigration"></div></div><p class="settings-caption">MyList v1.0.0</p>`;let old;try{old=JSON.parse(localStorage.getItem('mylist-demo-v1'))}catch{}if(Array.isArray(old)&&old.length&&!localStorage.getItem('mylist-imported-'+user.id))$('localMigration').innerHTML='<p>Există liste din versiunea anterioară pe acest dispozitiv.</p><button class="outline" onclick="importLocal()">Importă listele de pe dispozitiv</button>'}
async function invite(e){e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const {data,error}=await sb.functions.invoke('mylist-invite',{body:{email:$('inviteEmail').value.trim()}});if(error){let msg='Invitația nu a fost trimisă';try{msg=(await error.context.json()).error||msg}catch{}throw Error(msg)}toast(data.message);await load(true)}catch(e){handleError(e)}finally{b.disabled=false}}
